 print(k, [m.start() for m in list(re.finditer(re.escape(k),s,re.I))[:5]])
for n in ['999','1258','1462']:
 ms=list(re.finditer(r'(?m)^\s*'+n+r'\s*$',s));print('standalone',n,len(ms));
 for m in ms[:2]: print(repr(s[m.start():m.start()+290]))
print('replacement char',s.count('�'))
