6:*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top left,#253141,#10141b 65%);color:var(--text);font-family:system-ui,-apple-system,'Segoe UI',sans-serif}header{padding:25px max(20px,calc((100vw - 1270px)/2));display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--edge)}.brand{font-family:Georgia,serif;font-weight:700;letter-spacing:.12em;font-size:23px}.sub{color:var(--muted);font-size:13px;margin-top:4px}.tag{padding:7px 10px;border:1px solid #667688;border-radius:30px;color:#b4c8d5;font-size:12px}main{max-width:1270px;margin:auto;padding:23px 20px 70px}.intro{margin:0 0 22px;color:var(--muted);line-height:1.5}.layout{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(320px,.9fr);gap:18px}.panel{border:1px solid var(--edge);background:rgba(26,33,43,.90);border-radius:18px;padding:20px}.panel h2{margin:0 0 12px;font-size:17px;font-weight:650}.field{margin-top:18px}.lab{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:8px}.lab strong{font-size:14px}.lab span{font-size:12px;color:var(--muted)}select,input,textarea{font:inherit;color:var(--text);background:#111923;border:1px solid #536477;border-radius:9px;padding:10px;width:100%}select{max-width:100%;font-size:13px}select option{font-size:14px}input[type=checkbox]{width:auto;accent-color:var(--gold)}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}button{cursor:pointer;border:1px solid #687b8f;background:#273849;color:var(--text);padding:10px 13px;border-radius:10px;font-weight:600;font-size:13px}button:hover{background:#38516a}button.primary{background:#9c7347;color:#fff;border-color:#cf9c62}button.primary:hover{background:#b58754}button.ghost{background:transparent}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:2px}.small{font-size:12px;color:var(--muted)}.clause{padding:14px 0 16px;border-bottom:1px solid var(--edge)}.clause:last-of-type{border:0}.eyebrow{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);font-weight:700}.clause p{font:clamp(18px,2vw,25px)/1.42 Georgia,serif;margin:8px 0}.number{font-size:11px;color:#a8c4d0}.compose{background:#101923;border:1px solid #495a6e;border-radius:12px;padding:17px;margin:15px 0 18px;line-height:1.7;font:17px/1.6 Georgia,serif}.actions{display:flex;gap:8px;flex-wrap:wrap}.shelves{margin-top:20px;border-top:1px solid var(--edge);padding-top:16px}.saved{display:grid;gap:8px;margin-top:10px;max-height:320px;overflow:auto}.saveditem{padding:10px;background:#111923;border:1px solid #415369;border-radius:10px;display:flex;justify-content:space-between;align-items:center;gap:10px}.saveditem span{font-size:12px;color:#cbd7de}.helper{border-left:3px solid var(--green);padding-left:12px;margin-top:18px;color:#c0d6ca;line-height:1.6;font-size:13px}.filter{margin-top:11px}.foot{font-size:12px;color:var(--muted);line-height:1.6;margin-top:20px}.toast{min-height:20px;font-size:12px;color:var(--green);padding-top:8px}.preview{color:#f5eddf}.counts{color:var(--muted);font-size:13px}.locklabel{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:5px}.apphint{border-radius:8px;border:1px solid #57716c;padding:12px;font-size:13px;line-height:1.5;background:#1a2e2e;color:#d3e6dd}@media(max-width:850px){.layout{grid-template-columns:1fr}header{padding:20px} .panel{padding:16px}}
9:<main><p class="intro">Start with a protagonist, choose the complication that drives the action, and choose an outcome. Mix <em>any</em> A, B, and C clauses. Randomize, explore, and save promising combinations. This offline prototype is the first layer of the full Plotto system.</p>
