30:function render(){['A','B','C'].forEach(t=>{selects[t].value=String(state[t]);$(t+'Id').textContent='#'+state[t];$(t+'text').textContent=fmt(t)});$('combined').textContent=sentence();$('total').textContent='13,950 possible combinations';renderSaved();try{history.replaceState(null,'',location.href.split('#')[0]+`#A${state.A}-B${state.B}-C${state.C}`)}catch(e){}}
