34:function persist(){try{localStorage.setItem('plotto.studio.saved',JSON.stringify(saved));status('Saved in this browser.')}catch(e){status('Local save unavailable; use JSON export.')}}
35:function renderSaved(){let container=$('saved');container.replaceChildren();if(!saved.length){container.innerHTML='<div class="small">No saved plots yet.</div>';return}saved.forEach((r,i)=>{let box=document.createElement('div');box.className='saveditem';let label=document.createElement('span');label.textContent=`${r.title||'Untitled'} · A${r.A} B${r.B} C${r.C}`;let load=document.createElement('button');load.textContent='Open';load.addEventListener('click',()=>{state={A:r.A,B:r.B,C:r.C};$('searchB').value='';['A','B','C'].forEach(t=>choices(t));render();status('Saved plot loaded.')});let remove=document.createElement('button');remove.textContent='×';remove.ariaLabel='Delete saved plot';remove.addEventListener('click',()=>{saved.splice(i,1);persist();renderSaved()});box.append(label,load,remove);container.append(box)})}
