import json,re,pathlib,collections
p=pathlib.Path('/mnt/data')
d=json.loads((p/'plotto-conflicts-data.json').read_text());entries=d['entries']
# Conservative interpreter: preserve every character of source, classify only recognized grammar.
VAR=re.compile(r'(?<!\S)\(([a-z])\)(?=\s|$)')
REFGROUP=re.compile(r'\(([^()]*)\)')
TARGET=re.compile(r'(?<![\w])(?P<num>\d{1,4})(?P<var>[a-z])?(?=\b|[,*;\s-])',re.I)
CHANGE=re.compile(r'\bch\s+([A-Z][A-Z0-9-]*)\s+to\s+([A-Z][A-Z0-9-]*)',re.I)
TRANSPOSE=re.compile(r'\btr\s+([A-Z][A-Z0-9-]*)\s*(?:&|and)\s*([A-Z][A-Z0-9-]*)',re.I)
SCOPE=re.compile(r'(?<![\w])(?:\*\s*-\s*\*\*|\*\*\s*-\s*\*\*\*|\d{1,4}[a-z]?\s*-\s*\*\*|\d{1,4}[a-z]?\s*-\s*\*)',re.I)
metrics=collections.Counter(); edgeindex=[]
for rec in entries:
 txt=rec['text']; ms=list(VAR.finditer(txt));pieces=[]
 if not ms: splits=[('',0,len(txt))]
 else:
  splits=[(m.group(1),m.end(), ms[i+1].start() if i+1<len(ms) else len(txt)) for i,m in enumerate(ms)]
  if ms[0].start()>0 and txt[:ms[0].start()].strip(): splits.insert(0,('',0,ms[0].start()))
 for variant,start,end in splits:
  t=txt[start:end].strip(); groups=list(REFGROUP.finditer(t));leading=[]; trailing=[]
  # identify maximal run of parenthesized groups from beginning/end, separated by whitespace
  pos=0
  for m in groups:
   if not t[pos:m.start()].strip():leading.append(m);pos=m.end()
   else:break
  pos=len(t)
  for m in reversed(groups):
   if not t[m.end():pos].strip():trailing.append(m);pos=m.start()
   else:break
  trailing.reverse(); links=[]
  for m in groups:
   s=m.group(1).strip(); found=list(TARGET.finditer(s))
   if not found:continue
   direction='leadup' if m in leading else 'carryon' if m in trailing else 'uncertain'
   if m in leading and m in trailing:direction='uncertain'
   ops=[]
   for cm in CHANGE.finditer(s):ops.append({'op':'change','from':cm.group(1),'to':cm.group(2)})
   for tr in TRANSPOSE.finditer(s):ops.append({'op':'transpose','first':tr.group(1),'second':tr.group(2)})
   leftover=s
   for z in found[::-1]: leftover=leftover[:z.start()]+' '+leftover[z.end():]
   leftover=CHANGE.sub(' ',leftover);leftover=TRANSPOSE.sub(' ',leftover)
   leftover=re.sub(r'[\s,;:*\-]+','',leftover)
   # Retain all of original compound notation regardless of status
   parse_status='interpreted' if not leftover else 'partial'
   for f in found:
    target=int(f.group('num'));v=(f.group('var') or '').lower()
    if not 1<=target<=1462:continue
    link={'target':target,'variant':v,'direction':direction,'notation':s,'operations':ops,'status':parse_status,'source_variant':variant,'start':m.start()}
    links.append(link);edgeindex.append((rec['id'],variant,link));metrics[direction]+=1;metrics[parse_status]+=1
  pieces.append({'key':variant,'text':t,'links':links})
 rec['variants']=pieces
 metrics['records']+=1;metrics['variants']+=len(pieces)
validvariants={e['id']:{v['key'] for v in e['variants']} for e in entries}
for s,v,l in edgeindex:
 if l['variant'] and l['variant'] not in validvariants[l['target']]:
  l['status']='unresolved_target_variant';metrics['unresolved_target_variant']+=1
 d['parser']='Conservative grammar v2; classifications inferred only by position; inspect original for ambiguities'
d['parser_metrics']=dict(metrics)
(p/'plotto-conflicts-graph-v2.json').write_text(json.dumps(d,ensure_ascii=False,separators=(',',':')))
print(metrics)
# Upgrade existing browser app while retaining v1 story code support
html=(p/'plotto-studio-conflict-explorer.html').read_text()
old_start=html.index('const CONFLICTS=');old_end=html.index(';const MASTER=',old_start)
html=html[:old_start]+'const CONFLICTS='+json.dumps(entries,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')+html[old_end:]
html=html.replace('<div id="refs"></div>','<div id="variants"></div><div id="refs"></div><div id="transform"></div>')
html=html.replace('These are extracted references. Lead-up/carry-on direction and character transformations are not fully validated yet. Click a number to explore it.', 'Choose a variant, inspect proposed lead-ups and carry-ons, then apply a character-symbol transformation. OCR and ambiguous notation are explicitly flagged.')
html=html.replace('<button class="primary" id="add">+ Add to story</button>','<button class="primary" id="add">+ Add to story</button>')
# remove earlier misleading unsorted reference display by replace select function as function declaration later overriding initial function
extra=r'''
// Graph and transformation extension; original source remains untouched.
let activeVariant='',activeLink=null;
function formatLink(link){let mark=link.status==='interpreted'?'':' ⚠';return '#'+link.target+(link.variant||'')+mark+' · '+link.notation;}
function symbolicTransform(source,operations){
 // Exact token boundaries prevent accidental changes inside normal words / longer symbols.
 let text=source, map={};
 for(const op of operations||[]){if(op.op==='change'){map[op.from]=op.to}else if(op.op==='transpose'){map[op.first]=op.second;map[op.second]=op.first}}
 let keys=Object.keys(map).sort((a,b)=>b.length-a.length);
 if(!keys.length)return source;
 let rx=new RegExp('(?<![\\p{L}\\p{N}\\-])(?:'+keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![\\p{L}\\p{N}\\-])','gu');
 return source.replace(rx,m=>map[m]||m);
}
function showLink(link){
 activeLink=link;const target=byId[link.target];const chosen=target.variants.find(v=>v.key===link.variant)||target.variants[0];let panel=$('transform');panel.replaceChildren();
 let h=document.createElement('h3');h.textContent='Connection preview: #'+link.target+(link.variant||'');panel.append(h);
 let meta=document.createElement('p');meta.className='muted';meta.textContent='Relation: '+link.direction+' | Parse: '+link.status+' | Notation: ('+link.notation+')';panel.append(meta);
 let preview=document.createElement('div');preview.className='notice text';preview.textContent=symbolicTransform(chosen.text,link.operations);panel.append(preview);
 if(link.operations.length){let operations=document.createElement('p');operations.className='tag';operations.textContent=link.operations.map(o=>o.op==='change'?o.from+' → '+o.to:o.first+' ↔ '+o.second).join(' ; ');panel.append(operations)}
 let go=document.createElement('button');go.textContent='Open target conflict';go.onclick=()=>{select(link.target);activeVariant=link.variant;renderVariants()};panel.append(go);
}
function renderVariants(){
 const record=byId[selected], vbox=$('variants');vbox.replaceChildren();
 const lab=document.createElement('label');lab.textContent='Conflict variant';vbox.append(lab);
 const sel=document.createElement('select');sel.setAttribute('aria-label','Conflict variant');
 for(let v of record.variants){let op=document.createElement('option');op.value=v.key;op.textContent=v.key?'Variant '+v.key:'Whole / unlettered';sel.append(op)}
 if(!record.variants.some(v=>v.key===activeVariant))activeVariant=record.variants[0].key;
 sel.value=activeVariant;sel.onchange=()=>{activeVariant=sel.value;renderVariants()};vbox.append(sel);
 let v=record.variants.find(v=>v.key===activeVariant)||record.variants[0];
 let txt=document.createElement('p');txt.className='text';txt.textContent=v.text;vbox.append(txt);
 const refs=$('refs');refs.replaceChildren();
 for(const dir of ['leadup','carryon','uncertain']){
  let links=v.links.filter(l=>l.direction===dir);if(!links.length)continue;
  let heading=document.createElement('h3');heading.textContent=dir==='leadup'?'← Potential lead-ups':dir==='carryon'?'Potential carry-ons →':'? References requiring review';refs.append(heading);
  for(let link of links){let b=document.createElement('button');b.className='tiny';b.textContent=formatLink(link);b.title='Inspect original notation and transformations';b.onclick=()=>showLink(link);refs.append(b)}
 }
 if(!v.links.length)refs.textContent='No machine-recognized links for this variant.';
 $('transform').replaceChildren();
}
// Overrides original select() declaration by assigning at runtime.
select=function(n){if(!byId[n])return;selected=n;activeVariant='';const x=byId[n];$('title').textContent='Conflict #'+n;$('cat').textContent=x.category;$('entry').textContent='Select a variant below to inspect its text and references.';renderVariants();history.replaceState(null,'','#'+n)};
// Capture chosen variant and link-derived transformations in v2 story chain while keeping legacy PS1 codes readable.
let chainV2=[];
const originalAdd=$('add').onclick;
$('add').onclick=()=>{chainV2.push({id:selected,variant:activeVariant});originalAdd();};
const origClear=$('clear').onclick;
$('clear').onclick=()=>{chainV2=[];origClear();};
const origRestore=$('restore').onclick;
$('restore').onclick=()=>{origRestore();chainV2=chain.map(id=>({id,variant:''}))};
function v2code(){let d={v:2,a:abc[0],b:abc[1],c:abc[2],chain:chainV2};return 'PS2.'+btoa(JSON.stringify(d)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
// Existing PS1 codes remain canonical until the extended sequence editor is complete.
// This avoids losing or misrepresenting variant selections during reorder/delete.
'''
html=html.replace('</script></body>',extra+'</script></body>')
# reinitialize selected conflict after override
html=html.replace('select=function(n)', 'select=function(n)')
html=html.replace('// Capture chosen variant', 'select(selected);\n// Capture chosen variant')
(p/'plotto-studio-graph-v2.html').write_text(html)
