function allLinks(id,dir){let x=byId[id];if(!x)return [];return x.variants.flatMap(v=>v.links.filter(l=>l.direction===dir&&byId[l.target]&&l.status!=='unresolved_target_variant').map(l=>({...l,sourceVariant:v.key}))).filter(l=>l.target!==id)}
