function choose(links,rand,serendipity){const pool=links.slice().sort((a,b)=>weight(b)-weight(a)||a.target-b.target);if(!pool.length)return null;
 const spread=Math.max(1,Math.min(pool.length,Math.ceil(1+(pool.length-1)*serendipity/100)));
