function generate(){let anchor=safeInt($('seed').value,1,1462,999),before=safeInt($('before').value,0,6,2),after=safeInt($('after').value,0,6,3),seed=safeInt($('rngseed').value,0,2147483647,42),serendipity=safeInt($('randomness').value,0,100,30);
