 for(let i=0;i<before;i++){let possibilities=allLinks(cursor,'leadup').filter(l=>!used.has(l.target));let pick=choose(possibilities,rand,serendipity);if(!pick)break;left.unshift(card(pick.target,pick.variant,pick));used.add(pick.target);cursor=pick.target}
