function setupMaster(){for(let [i,key] of ['A','B','C'].entries()){let label=document.createElement('label');label.textContent=key+' clause';let sel=document.createElement('select');for(let entry of DATA.master[key]){let o=document.createElement('option');o.value=entry.id;o.textContent=entry.id+' · '+entry.text;sel.append(o)}sel.value=abc[i];sel.onchange=()=>{abc[i]=Number(sel.value);renderStory()};$('master').append(label,sel)}}
function encode(){let payload={v:3,abc,steps,parameters};let b=unescape(encodeURIComponent(JSON.stringify(payload)));return 'PS3.'+btoa(b).replace(/\\+/g,'-').replace(/\\//g,'_').replace(/=+$/,'')}
