function roleSwap(text,operations){let map={};let warnings=[];for(let op of operations||[]){if(!op||!allowedRole.test(op.from||'')||!allowedRole.test(op.to||'')){warnings.push('Unsupported transformation: '+JSON.stringify(op));continue;}if(op.op==='change')map[op.from]=op.to;else if(op.op==='transpose'){map[op.from]=op.to;map[op.to]=op.from}else warnings.push('Unrecognized operation: '+op.op)}return {text:text.replace(rolePattern,t=>map[t]||t),warnings,map}}
