const byId=Object.fromEntries(DATA.entries.map(x=>[x.id,x]));
const $=id=>document.getElementById(id);
let abc=[7,41,13], steps=[], current=999, lastRoute=[];
let parameters={before:2,after:3,serendipity:30,seed:42};
let cast={"A":"","B":"","A-2":"","A-3":"","NW":"","F-B":""};
const safeInt=(x,lo,hi,def)=>{const n=Number(x);return Number.isInteger(n)&&n>=lo&&n<=hi?n:def};
function variantOf(id,key=''){let x=byId[id];return x&&(x.variants.find(v=>v.key===key)||x.variants[0])}
function excerpt(s,n=140){return s.replace(/\s+/g,' ').trim().slice(0,n)}
function card(id,key='',link=null){let v=variantOf(id,key);return {id,key:v?.key||'',link:link?{notation:link.notation,direction:link.direction,status:link.status,operations:link.operations}:null}}
function allLinks(id,dir){let x=byId[id];if(!x)return [];return x.variants.flatMap(v=>v.links.filter(l=>l.direction===dir&&byId[l.target]&&l.status!=='unresolved_target_variant').map(l=>({...l,sourceVariant:v.key}))).filter(l=>l.target!==id)}
// The extracted graph contains spuriously recognized targets in some OCR compounds; prefer conservative links.
function weight(l){let x=l.status==='interpreted'?1:l.status==='corrected_with_secondary_source'?.92:.42;return x}
function rng(seed){let x=seed>>>0;return ()=>{x=(Math.imul(1664525,x)+1013904223)>>>0;return x/4294967296}}
function choose(links,rand,serendipity){const pool=links.slice().sort((a,b)=>weight(b)-weight(a)||a.target-b.target);if(!pool.length)return null;
 const spread=Math.max(1,Math.min(pool.length,Math.ceil(1+(pool.length-1)*serendipity/100)));
 return pool[Math.floor(rand()*spread)]}
function generate(){let anchor=safeInt($('seed').value,1,1462,999),before=safeInt($('before').value,0,6,2),after=safeInt($('after').value,0,6,3),seed=safeInt($('rngseed').value,0,2147483647,42),serendipity=safeInt($('randomness').value,0,100,30);
 parameters={before,after,seed,serendipity};let rand=rng(seed),left=[],right=[],used=new Set([anchor]);let cursor=anchor;
 for(let i=0;i<before;i++){let possibilities=allLinks(cursor,'leadup').filter(l=>!used.has(l.target));let pick=choose(possibilities,rand,serendipity);if(!pick)break;left.unshift(card(pick.target,pick.variant,pick));used.add(pick.target);cursor=pick.target}
 cursor=anchor;
 for(let i=0;i<after;i++){let possibilities=allLinks(cursor,'carryon').filter(l=>!used.has(l.target));let pick=choose(possibilities,rand,serendipity);if(!pick)break;right.push(card(pick.target,pick.variant,pick));used.add(pick.target);cursor=pick.target}
 steps=[...left,card(anchor),...right];current=anchor;render();notify('Generated '+steps.length+' situation(s) using source references.');}
function show(id){current=safeInt(id,1,1462,current);$('seed').value=current;renderExplorer()}
function renderExplorer(){let x=byId[current];$('anchor').textContent=x.category;let root=$('current');root.replaceChildren();let title=document.createElement('h3');title.textContent='Conflict #'+current+' · '+x.category;root.append(title);
 for(let v of x.variants){let wrap=document.createElement('article');let name=document.createElement('strong');name.textContent=v.key?'Variant '+v.key:'Unlettered';let para=document.createElement('p');para.className='text';para.textContent=v.text;let add=document.createElement('button');add.textContent='+ Add '+current+(v.key||'');add.onclick=()=>{steps.push(card(current,v.key));renderStory()};wrap.append(name,para,add);root.append(wrap)}
 let el=$('links');el.replaceChildren();for(let dir of ['leadup','carryon','uncertain']){let ls=allLinks(current,dir);if(!ls.length)continue;let t=document.createElement('h3');t.textContent=dir==='leadup'?'← Possible lead-ups':dir==='carryon'?'Possible carry-ons →':'? Uncertain references';el.append(t);for(let l of ls){let b=document.createElement('button');b.style.margin='3px';b.textContent='#'+l.target+(l.variant||'')+(l.status==='interpreted'?'':' ⚠');b.title='Notation: '+l.notation+' | '+l.status;b.onclick=()=>{steps.push(card(l.target,l.variant,l));show(l.target);renderStory()};el.append(b)}}}
function setupMaster(){for(let [i,key] of ['A','B','C'].entries()){let label=document.createElement('label');label.textContent=key+' clause';let sel=document.createElement('select');for(let entry of DATA.master[key]){let o=document.createElement('option');o.value=entry.id;o.textContent=entry.id+' · '+entry.text;sel.append(o)}sel.value=abc[i];sel.onchange=()=>{abc[i]=Number(sel.value);renderStory()};$('master').append(label,sel)}}
function encode(){let payload={v:4,abc,steps,parameters,cast};let b=unescape(encodeURIComponent(JSON.stringify(payload)));return 'PS4.'+btoa(b).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function decode(raw){let code=raw.trim();if(!/^PS[134]\./.test(code))throw Error('Only PS1, PS3, and PS4 addresses are supported');let part=code.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');let s=decodeURIComponent(escape(atob(part)));let obj=JSON.parse(s);if(code.startsWith('PS1.')){let a=obj.a??obj.abc?.[0],b=obj.b??obj.abc?.[1],c=obj.c??obj.abc?.[2],chain=obj.chain||[];return {abc:[a,b,c],steps:chain.map(id=>card(Number(id)))};}if(![3,4].includes(obj.v)||!Array.isArray(obj.abc)||!Array.isArray(obj.steps))throw Error('Invalid story code');if(obj.steps.length>1000)throw Error('Story exceeds allowed length');if(obj.steps.some(z=>!byId[z.id]||typeof z.key!=='string'||z.key.length>1))throw Error('Unknown conflicts or variants');return obj}
function renderStoryV3(){let holder=$('story');holder.replaceChildren();if(!steps.length)holder.textContent='No situations selected yet.';
 steps.forEach((s,i)=>{let el=document.createElement('article');let title=document.createElement('strong');title.textContent=(i+1)+'. #'+s.id+(s.key||'');let p=document.createElement('p');p.className='text';p.textContent=variantOf(s.id,s.key)?.text||'';let row=document.createElement('div');row.className='step-tools';for(let [name,fn] of [['Inspect',()=>show(s.id)],['↑',()=>{if(i){[steps[i-1],steps[i]]=[steps[i],steps[i-1]];renderStory()}}],['↓',()=>{if(i<steps.length-1){[steps[i+1],steps[i]]=[steps[i],steps[i+1]];renderStory()}}],['Remove',()=>{steps.splice(i,1);renderStory()}]]){let b=document.createElement('button');b.textContent=name;b.onclick=fn;row.append(b)}el.append(title,p);if(s.link){let meta=document.createElement('p');meta.className='muted';meta.textContent='Via '+s.link.direction+': ('+s.link.notation+') ['+s.link.status+']';el.append(meta)}el.append(row);holder.append(el)});
 $('address').value=encode();try{localStorage.setItem('plotto-studio-v4',encode())}catch{}}
function render(){renderExplorer();renderStory()}
function notify(s){$('message').textContent=s}
function findPath(start,end,max=8){if(start===end)return [card(start)];let queue=[start],seen=new Set([start]),prev=new Map(),depth=new Map([[start,0]]);
 while(queue.length){let n=queue.shift();if(depth.get(n)>=max)continue;for(let link of allLinks(n,'carryon')){let m=link.target;if(seen.has(m))continue;seen.add(m);prev.set(m,{n,link});depth.set(m,depth.get(n)+1);if(m===end){let arr=[card(end,link.variant,link)];while(m!==start){let q=prev.get(m);m=q.n;if(m!==start)arr.unshift(card(m,q.link.variant,q.link))}arr.unshift(card(start));return arr}queue.push(m)}}return []}
function download(name,content,mime){let url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
$('search').oninput=()=>{let q=$('search').value.trim().toLowerCase(),el=$('matches');el.replaceChildren();if(!q)return;let matched=DATA.entries.filter(x=>String(x.id)===q||x.variants.some(v=>v.text.toLowerCase().includes(q))).slice(0,35);for(let x of matched){let b=document.createElement('button');b.className='item';b.textContent='#'+x.id+' '+excerpt(x.variants[0]?.text||'');b.onclick=()=>show(x.id);el.append(b)}};
