app=BASE/'plotto-studio-continuity-v5.html'
def payload(f):
    s=BeautifulSoup(Path(f).read_text(encoding='utf-8'),'html.parser').find('script').text
    return json.loads(re.search(r'window\.__PAYLOAD__\s*=\s*(\{.*\})\s*;',s,re.S).group(1))
keys=[('paleo74104','74,104 BCE','3Any Human Ever_ one life from over 100 billion.html'),('ancient1914','1914 BCE','Any Human Ever_ one life from over 100 billion.html')]
