    'base_place':p['birthplace'],'base_region':p['region_label'],'birth_places':[{k:v for k,v in bp.items() if k in ('subregion','label','nearest_town','lat','lon','region','region_label','people','country_label')} for bp in p['birth_places'] if bp.get('people',0)>0],
    'life_expectancy':d['life_expectancy'],'survive15':d['surviving_to_15_pct']/100,
    'causes':d['causes'],'marriage_age':d['family']['marriage_age'],'ever_married':d['family']['ever_married_pct']/100,'children_per_woman':d['family']['children_per_woman'],
    'sources':[{'id':x['id'],'citation':x['citation'],'provenance':x.get('provenance','')} for x in p['birth_distribution_sources']],
    'weight_basis':'saved 2026 Any Human Ever snapshot, approximate historical population by geographic subregion' })
# Extract archived life descriptions from the PDF printouts (replay mode only)
archive=[]
for f in sorted(BASE.glob('*Any Human Ever*.pdf')):
    txt=subprocess.check_output(['pdftotext','-layout',str(f),'-']).decode('utf8','replace')
    num=re.match(r'(\d+)',f.name).group(1)
    m=re.search(r'(?:This is not a real person, but (?:his|her) life story|\w+ is not a real person\. But (?:his|her) life story).*?\bin (?:the )?(.*?) in ([\d,]+) (BCE|CE)',txt,re.S)
